#!/bin/sh
python3 -c 'q='"'"'import sys,json\ns=sys.argv[1] if len(sys.argv)>1 else \'"'"'1011\'"'"'\nR=json.loads(sys.argv[2]) if len(sys.argv)>2 else {\'"'"'0,0\'"'"':[0,\'"'"'0\'"'"',1],\'"'"'0,1\'"'"':[0,\'"'"'1\'"'"',1],\'"'"'0,_\'"'"':[1,\'"'"'_\'"'"',-1],\'"'"'1,1\'"'"':[1,\'"'"'0\'"'"',-1],\'"'"'1,0\'"'"':[2,\'"'"'1\'"'"',0],\'"'"'1,_\'"'"':[2,\'"'"'1\'"'"',0]}\nstate=h=0;t={i:c for i,c in enumerate(s) if c!=\'"'"'_\'"'"'};hist=[]\nwhile True:\n hist.append([state,h,sorted(t.items())]);v=R.get(str(state)+\'"'"',\'"'"'+t.get(h,\'"'"'_\'"'"'))\n if v is None:break\n state,w,d=v\n if w==\'"'"'_\'"'"':t.pop(h,None)\n else:t[h]=w\n h+=d\nb=json.dumps([R,s,hist],sort_keys=True,separators=(\'"'"',\'"'"',\'"'"':\'"'"')).encode()\ndef G(b):\n a=1\n for v in b:a=a*257+v+1\n return a\ndef D(a):\n v=[]\n while a>1:\n  a,r=divmod(a,257);assert r;v.append(r-1)\n return bytes(v[::-1])\ndef P(b):\n g=1;pr=[];k=2\n while len(pr)<len(b):\n  if all(k%p for p in pr if p*p<=k):pr.append(k);g*=k**(b[len(pr)-1]+1)\n  k+=1\n return g,pr\np=\'"'"'\'"'"';src=\'"'"'\'"'"'\n# source self-description is supplied by quine wrapper via global SOURCE\nsrc=("q="+repr(q)+";exec(q)").encode();selfcode=G(src);assert D(selfcode)==src\nbundle=json.dumps([R,s,hist],sort_keys=True,separators=(\'"'"',\'"'"',\'"'"':\'"'"')).encode()\na=G(bundle);assert D(a)==bundle\ng,pr=P(bundle);z=g;out=[]\nfor p in pr:\n e=0\n while z%p==0:z//=p;e+=1\n out.append(e-1)\nassert z==1 and bytes(out)==bundle\nphase=(-1)**((bin(a).count(\'"'"'1\'"'"')+bin(g).count(\'"'"'1\'"'"')+bin(selfcode).count(\'"'"'1\'"'"'))%2)\nprint(json.dumps(dict(steps=len(hist)-1,self_source_verified=D(selfcode)==src,self_code_bits=selfcode.bit_length(),base257_bits=a.bit_length(),prime_bits=g.bit_length(),dual_roundtrip=True,H_phase_H=[(1+phase)/2,(1-phase)/2],pure_state_entropy=0,conditional_next_entropy=0),separators=(\'"'"',\'"'"',\'"'"':\'"'"')))\n'"'"';exec(q)' "$@"
